-- Patch v18, academy gamification e modulo economia privata
CREATE TABLE IF NOT EXISTS academy_access(id BIGINT AUTO_INCREMENT PRIMARY KEY,account_id BIGINT NOT NULL,strato VARCHAR(16) NOT NULL,pv_al_momento INT NOT NULL DEFAULT 0,created_at VARCHAR(40) NOT NULL,INDEX(account_id),INDEX(strato)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS academy_corsi_completati(id BIGINT AUTO_INCREMENT PRIMARY KEY,account_id BIGINT NOT NULL,corso VARCHAR(200) NOT NULL,strato VARCHAR(16) NOT NULL,reward_pv INT NOT NULL DEFAULT 0,created_at VARCHAR(40) NOT NULL,INDEX(account_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_movimenti(id BIGINT AUTO_INCREMENT PRIMARY KEY,tipo VARCHAR(12) NOT NULL,categoria VARCHAR(60),descrizione VARCHAR(255),importo DECIMAL(12,2) NOT NULL,data_mov VARCHAR(20) NOT NULL,fonte VARCHAR(40),created_at VARCHAR(40) NOT NULL,INDEX(data_mov),INDEX(tipo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_fatture(id BIGINT AUTO_INCREMENT PRIMARY KEY,tipo VARCHAR(8) NOT NULL,numero VARCHAR(40),controparte VARCHAR(200),imponibile DECIMAL(12,2) NOT NULL,iva DECIMAL(12,2) NOT NULL,totale DECIMAL(12,2) NOT NULL,data_fat VARCHAR(20) NOT NULL,created_at VARCHAR(40) NOT NULL,INDEX(tipo),INDEX(data_fat)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_obiettivi(id BIGINT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,target DECIMAL(12,2) NOT NULL,attuale DECIMAL(12,2) NOT NULL DEFAULT 0,unita VARCHAR(8),updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
